CREATE TABLE IF NOT EXISTS "site_concurrency_leases" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "site_id" INTEGER NOT NULL, "lease_token" TEXT NOT NULL, "slot" INTEGER NOT NULL, "expires_at" TEXT NOT NULL, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
ALTER TABLE "sites" ADD COLUMN "max_concurrency" INTEGER;
ALTER TABLE "sites" ADD COLUMN "concurrency_wait_timeout_ms" INTEGER NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX "site_concurrency_leases_site_slot_unique" ON "site_concurrency_leases" ("site_id", "slot");
CREATE UNIQUE INDEX "site_concurrency_leases_token_unique" ON "site_concurrency_leases" ("lease_token");
CREATE INDEX "site_concurrency_leases_expires_at_idx" ON "site_concurrency_leases" ("expires_at");
CREATE INDEX "site_concurrency_leases_site_id_idx" ON "site_concurrency_leases" ("site_id");
